CREATE TABLE site_archive_runs(id INTEGER PRIMARY KEY AUTOINCREMENT,site_id TEXT NOT NULL,started_at INTEGER NOT NULL,finished_at INTEGER,status TEXT NOT NULL,message TEXT NOT NULL);
